// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { Button } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Actions/Button)

figma.connect(Button, FIGMA_NODE_URL, {
  props: {
    variant: figma.enum('variant', { 'solid': 'solid', 'subtle': 'subtle', 'ghost': 'ghost' }),
    intent: figma.enum('intent', { 'positive': 'positive', 'negative': 'negative', 'brand': 'brand', 'primary': 'primary', 'destructive': 'destructive', 'neutral': 'neutral' }),
    size: figma.enum('size', { 'sm': 'sm', 'md': 'md', 'lg': 'lg', 'xl': 'xl' }),
    isLoading: figma.boolean('isLoading'),
    iconStart: figma.boolean('hasIconStart', { true: figma.instance('iconStart'), false: undefined }),
    iconEnd: figma.boolean('hasIconEnd', { true: figma.instance('iconEnd'), false: undefined }),
    fullWidth: figma.boolean('fullWidth'),
    label: figma.string('label'),
  },
  example: ({ label, variant, intent, size, isLoading, iconStart, iconEnd, fullWidth }) => (
    <Button variant={variant} intent={intent} size={size} isLoading={isLoading} iconStart={iconStart} iconEnd={iconEnd} fullWidth={fullWidth}>{label}</Button>
  ),
});
